// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address fuzz_baseToken, address fuzz_nft, uint128 fuzz_vBase, uint128 fuzz_vNft, uint56 fuzz_changeFee, uint16 fuzz_feeRate, bytes32 fuzz_merkleRoot, bool fuzz_useStolen, bool fuzz_payRoyalties) public {
        vm.assume(fuzz_feeRate <= 5000);

        bool ok;
        try c.initialize(fuzz_baseToken, fuzz_nft, fuzz_vBase, fuzz_vNft, fuzz_changeFee, fuzz_feeRate, fuzz_merkleRoot, fuzz_useStolen, fuzz_payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.baseToken() == fuzz_baseToken);
        }
    }
}
